            alt="Colorful mountain landscape at sunset"
          >
        </div>

        <div class="details">
          <h2>Sunset Ridge</h2>
          <p>A high-resolution image saved in your travel inspiration collection.</p>
          <ul class="meta" aria-label="Image metadata">
            <li><strong>Collection</strong> Travel inspiration</li>
            <li><strong>Size</strong> 2400 x 1800 pixels</li>
            <li><strong>Uploaded</strong> April 18, 2026</li>
          </ul>
          <button class="trigger" type="button" aria-haspopup="dialog">Delete image</button>
          <p class="status" id="delete-status" tabindex="-1" aria-live="polite"></p>
        </div>
      </article>
    </main>

    <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
      <form class="dialog-panel" method="dialog">
        <div class="dialog-header">
          <h2 id="dialog-title">Delete this image?</h2>
          <button class="dialog-close" type="submit" value="cancel" aria-label="Close delete confirmation dialog">Close</button>
        </div>
        <p id="dialog-description">
          This will remove "Sunset Ridge" from your library. This action cannot be undone.
        </p>
        <div class="dialog-actions">
          <button type="submit" value="cancel">Keep image</button>
          <button class="danger-button" type="submit" value="delete">Delete image</button>
        </div>
      </form>
    </dialog>

    <script>
      const deleteTrigger = document.querySelector(".trigger");
      const deleteDialog = document.querySelector("#delete-dialog");
      const imagePreview = document.querySelector("#image-preview");
      const deleteStatus = document.querySelector("#delete-status");
      let lastFocusedElement = null;

      deleteTrigger.addEventListener("click", () => {
        lastFocusedElement = document.activeElement;
        deleteDialog.showModal();
      });

      deleteDialog.addEventListener("close", () => {
        if (deleteDialog.returnValue === "delete") {
          imagePreview.hidden = true;
          deleteStatus.textContent = "Sunset Ridge has been deleted from your library.";
          document.querySelector("main").append(deleteStatus);
          deleteStatus.focus();
          return;
        }

        if (lastFocusedElement) {
          lastFocusedElement.focus();
        }
      });

      deleteDialog.addEventListener("click", (event) => {
        if (event.target === deleteDialog) {
          deleteDialog.close("cancel");
        }
      });
    </script>
  </body>
</html>
