       .image-frame {
         min-width: 0;
         padding: 0.75rem;
         border: 1px solid var(--surface-soft);
         border-radius: 1.5rem;
         background: #020617;
       }

       .image-frame img {
         display: block;
         width: 100%;
         max-width: 100%;
         height: auto;
         border-radius: 1rem;
         aspect-ratio: 4 / 3;
         object-fit: cover;
       }

       .details {
         min-width: 0;
       }

       .details h2 {
         margin: 0 0 0.75rem;
         font-size: clamp(1.5rem, 5vw, 2.5rem);
         line-height: 1.05;
       }

       .details p {
         margin: 0 0 1.5rem;
         color: var(--muted);
       }

       .meta {
         display: grid;
         gap: 0.75rem;
         margin: 0 0 1.5rem;
         padding: 0;
         list-style: none;
         color: var(--muted);
       }

       .meta strong {
         display: block;
         color: var(--text);
       }

       button {
         border: 1px solid transparent;
         border-radius: 999px;
         padding: 0.8rem 1.1rem;
         font: inherit;
         font-weight: 800;
         color: var(--text);
         background: var(--button);
         cursor: pointer;
       }

       button:hover {
         background: var(--button-hover);
       }

       button:focus-visible,
       a:focus-visible {
         outline: 3px solid var(--ring);
         outline-offset: 4px;
       }

       .trigger,
       .danger-button {
         background: var(--danger-strong);
       }

       .trigger:hover,
       .danger-button:hover {
         background: var(--danger-hover);
       }

       .status {
         min-height: 1.5rem;
         margin-top: 1rem;
         color: var(--accent);
         font-weight: 700;
       }

       dialog {
         width: min(100% - 2rem, 32rem);
         margin: auto;
         padding: 0;
         border: 1px solid var(--border);
         border-radius: 1.5rem;
         color: var(--text);
         background: var(--surface);
         box-shadow: 0 2rem 7rem #000000;
       }

       dialog::backdrop {
         background: #020617;
       }

       .dialog-panel {
         padding: clamp(1.25rem, 6vw, 2rem);
         background:
           linear-gradient(135deg, #1e293b, transparent 45%),
           var(--surface);
       }

       .dialog-header {
         display: flex;
         gap: 1rem;
         align-items: start;
         justify-content: space-between;
       }

       .dialog-header h2 {
         margin: 0;
         font-size: clamp(1.35rem, 6vw, 2rem);
         line-height: 1.1;
       }

       .dialog-close {
         flex: 0 0 auto;
         padding: 0.55rem 0.9rem;
       }

       .dialog-panel p {
         margin: 1rem 0 0;
         color: var(--muted);
       }

       .dialog-actions {
         display: flex;
         flex-wrap: wrap;
         gap: 0.75rem;
         justify-content: end;
         margin-top: 1.75rem;
       }

       .dialog-actions button {
         min-width: 8rem;
       }

       @media (max-width: 46rem) {
         .preview-card {
           grid-template-columns: 1fr;
         }

         .dialog-actions {
           justify-content: stretch;
         }

